{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요구 기능과 하중, 조립·가공 조건을 부품 설계에 연결하는 능력을 검증한다. 질문은 축 지름을 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "교재에 주어진 하중 조건으로 감속기 축 지름과 베어링을 선정한 과제의 요구 기능과 설계 조건을 설명한다.",
          "task": "주어진 하중을 지지하면서 베어링 등 상대 부품과 조립할 수 있는 축의 주요 치수를 정해야 했음을 설명한다.",
          "action": "축에 작용하는 하중과 전달 경로를 파악하고, 재질의 허용응력 및 상대 부품의 규격을 연결해 축 지름을 정한 근거를 설명한다. 형상과 가공·조립 조건 중 실제 검토한 내용을 구분해 제시한다.",
          "result": "선정한 축 지름을 계산서나 손도면의 내용과 연결하고, 해당 치수가 요구 하중과 조립 조건을 충족한다고 판단한 근거를 설명한다."
        },
        "expectedEvidence": [
          "축 지름을 정한 구체적인 근거와 그 근거가 주어진 하중 조건에 연결되는 설명",
          "하중이 축과 지지 부품으로 전달되는 경로에 대한 이해",
          "재질의 특성과 하중 조건을 형상 및 주요 치수 결정에 반영한 내용",
          "베어링 등 상대 부품의 규격과 가공·조립 조건을 검토한 내용",
          "최종 선정 치수가 요구 조건에 부합하는지 확인한 계산 또는 도면상의 근거"
        ]
      },
      "question": "기계요소설계 수업 과제: 감속기 축 설계 계산에서 축 지름과 베어링을 선정하셨는데요, 축 지름을 정한 근거는 무엇이었나요?",
      "answerTip": "본인이 수행한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "주어진 하중과 하중 전달 경로를 구체적으로 설명하고, 이를 축 지름 선정의 계산 근거와 연결한다.",
            "재질의 특성, 형상, 상대 부품의 규격 및 가공·조립 조건이 주요 치수 결정에 미친 영향을 설명한다.",
            "선정한 치수와 계산서 또는 손도면의 내용을 연결하여 요구 조건 충족 여부를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "하중 조건이나 계산 결과를 근거로 축 지름을 선정한 이유는 설명하지만 하중 경로와의 연결이 부분적이다.",
            "재질, 상대 부품, 가공·조립 조건에 대한 검토 일부는 확인되지만 치수 결정과의 연결 또는 최종 확인 근거가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "축 지름을 제시하거나 공식 사용 사실만 말하고 하중 조건에 따른 선정 근거를 설명하지 못한다.",
            "하중 경로와 상대 부품의 관계를 설명하지 못하며, 형상·재질·주요 치수를 정한 근거가 확인되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "3D 모델을 제작 가능한 양산 도면으로 구체화하는 능력을 검증한다. 질문은 베어링 조립부의 기능을 근거로 치수 공차를 좁힐 필요성을 판단하는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "감속기 축의 3D 모델을 가공·조립 담당자가 사용할 양산용 2D 도면으로 정리해야 하는 상황이다.",
          "task": "베어링 조립부의 기능을 충족하는 공차를 정하면서 기능상 필요하지 않은 치수까지 불필요하게 엄격하게 지정하지 않아야 한다.",
          "action": "베어링과 축의 끼워맞춤 및 허용 가능한 조립 상태를 기준으로 치수 공차의 필요 범위를 판단한다. 관련 기준면과 기하 공차, 표면 처리 요구를 도면에 명시하고 기능상 중요하지 않은 치수에는 적절한 일반 공차를 적용할 계획을 설명한다.",
          "result": "기능에 필요한 부위의 요구사항과 일반 치수의 구분이 명확하고, 가공·조립 담당자가 임의로 해석하지 않아도 제작할 수 있는 도면의 상태를 제시한다."
        },
        "expectedEvidence": [
          "베어링 조립부의 치수 공차를 좁힐지 판단하는 기능 및 끼워맞춤 기준",
          "기능상 중요한 치수와 일반 공차로 관리할 치수를 구분하는 근거",
          "조립 기능에 필요한 기준면과 기하 공차를 연결해 지정하는 계획",
          "부품의 기능에 필요한 표면 처리 요구를 도면에 명시하는 계획",
          "3D 모델을 바탕으로 가공·조립에 필요한 치수와 요구사항을 빠짐없이 전달할 수 있는 2D 도면 구성"
        ]
      },
      "question": "감속기 축의 3D 모델을 양산용 2D 도면으로 정리할 때, 베어링 조립부의 치수 공차를 일반 치수보다 좁게 지정할지 판단하는 기준은 무엇으로 삼으시겠어요?",
      "answerTip": "상황을 구체적으로 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "베어링 조립부의 기능과 끼워맞춤 요구를 근거로 치수 공차의 필요 범위를 판단하며, 무조건 좁은 공차를 적용하지 않는다.",
            "기능 치수와 일반 치수를 구분하고, 필요한 기준면·기하 공차·표면 처리 요구를 도면에 반영하는 구체적인 계획을 설명한다.",
            "가공·조립 담당자가 별도 추정 없이 제작할 수 있도록 치수와 요구사항을 명확하게 전달하는 도면의 완성 상태를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "베어링의 끼워맞춤이나 조립 기능을 공차 판단 기준으로 제시하지만 필요한 공차 범위를 정하는 설명은 부분적이다.",
            "기능 치수와 일반 치수의 구분은 확인되지만 기하 공차, 표면 처리 또는 제작 가능한 도면 구성에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "기능이나 끼워맞춤에 대한 근거 없이 모든 공차를 좁히거나 임의의 공차를 지정하겠다고 답한다.",
            "3D 형상을 2D로 옮기는 설명에 그치며 치수 공차, 기하 공차, 표면 처리 등 제작에 필요한 요구사항을 구체화하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P06",
  "interviews": [
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "잠재 거래처를 선별하고 담당자와 접점을 만들어 첫 미팅으로 연결할 수 있는지 검증한다. 질문은 우선 연락할 거래처 후보를 고르는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "신규 거래처를 발굴해 제품 소개나 제안을 위한 첫 미팅을 확보해야 하는 상황이다.",
          "task": "구매 가능성이 있는 거래처 후보를 목록화하고 우선 접촉할 대상을 선정해야 한다.",
          "action": "업종, 규모, 구매 가능성에 관한 정보를 바탕으로 후보를 선별하고, 전화·소개·방문 중 적절한 방법으로 담당자에게 접근해 미팅을 제안한다.",
          "result": "담당자와 제품 소개 또는 제안 미팅의 일정과 목적을 확정하는 등 첫 미팅 확보 여부를 확인할 수 있는 예상 결과를 제시한다."
        },
        "expectedEvidence": [
          "우선 연락할 후보의 선정 기준과 해당 기준이 제품 구매 가능성과 연결되는 이유",
          "선정 기준에 필요한 정보를 찾아 잠재 거래처 목록을 구성하는 방법",
          "거래처 담당자를 확인하고 전화·소개·방문으로 접점을 만드는 구체적인 방법",
          "담당자의 관심을 제품 소개나 제안을 위한 첫 미팅 약속으로 연결하는 방법"
        ]
      },
      "question": "신규 거래처 발굴을 맡아 첫 제품 소개 미팅을 잡아야 한다면, 우선 연락할 거래처 후보를 고르는 기준은 무엇으로 정하시겠어요?",
      "answerTip": "구체적인 상황을 떠올려 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "업종, 규모, 구매 가능성을 제품 특성과 연결하여 우선 연락할 후보의 선정 기준을 구체적으로 설명한다.",
            "기준에 맞는 정보를 확보해 후보 목록을 구성하고 담당자에게 접근하는 실행 방안이 명확하다.",
            "담당자 접촉을 첫 미팅 제안으로 연결하는 행동과 미팅 확보 여부를 확인할 예상 결과가 구체적이다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구매 가능성과 관련된 후보 선정 기준을 제시하지만, 기준의 적용 방식이나 정보 확보 방법은 일부 부족하다.",
            "담당자 접촉과 미팅 제안 방향은 제시하지만, 실제 접점 형성 방법이나 약속 확정 방식이 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "후보 선정 기준이 없거나 단순히 가까운 곳, 아는 곳 등 구매 가능성과의 관련성을 설명하지 못한다.",
            "불특정 다수에게 연락하겠다는 수준에 머물러 후보 목록 구성, 담당자 접촉, 첫 미팅 연결에 필요한 근거가 부족하다."
          ]
        }
      }
    },
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기존 거래처의 발주 변화와 요구를 파악해 거래 유지·확대로 연결할 수 있는지 검증한다. 질문은 발주 감소 상황에서 가장 먼저 확인할 정보에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "정기적으로 연락하던 기존 거래처의 발주량이 평소보다 줄어 거래 이탈 가능성을 살펴봐야 하는 상황이다.",
          "task": "발주 감소가 평소 구매 주기에 따른 변화인지, 불만이나 수요 변화에 따른 신호인지 파악해야 한다.",
          "action": "기존 발주 패턴과 최근 변화를 비교하고 담당자와의 연락으로 불만 및 추가 수요를 확인한 뒤, 파악한 원인에 맞는 거래 유지 대응이나 추가 제품 제안을 정한다.",
          "result": "후속 연락과 발주 추이 확인을 통해 거래 유지 또는 추가 제품 발주 여부를 판단할 수 있는 예상 결과를 제시한다."
        },
        "expectedEvidence": [
          "발주 감소 상황에서 가장 먼저 확인할 정보와 이를 우선 확인하는 이유",
          "정기 방문이나 연락으로 평소 발주 패턴과 최근 변화를 파악하는 방법",
          "거래처 담당자에게 불만과 추가 수요를 확인하는 구체적인 방법",
          "확인된 원인에 맞춰 이탈 신호에 대응하거나 추가 제품을 제안하는 행동",
          "후속 연락과 발주 변화를 통해 거래 유지·확대 여부를 확인하는 방법"
        ]
      },
      "question": "정기적으로 연락하던 기존 거래처의 발주량이 평소보다 줄어든 상황이라면, 거래 유지를 위해 가장 먼저 무엇을 확인하시겠어요?",
      "answerTip": "생각을 정리한 뒤 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가장 먼저 확인할 정보를 명확히 지목하고, 발주 감소 원인이나 이탈 가능성을 파악하는 데 필요한 이유를 설명한다.",
            "평소 발주 패턴과 최근 변화를 비교하고 정기적인 접촉으로 불만과 추가 수요를 확인하는 방안이 구체적이다.",
            "확인된 원인에 맞는 유지 대응 또는 추가 제품 제안과 이후 발주 변화를 확인할 방법이 연결되어 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "발주 감소 원인과 관련된 확인 정보를 제시하지만, 우선 확인하는 이유나 평소 패턴과의 비교가 충분하지 않다.",
            "거래처 연락과 원인에 따른 대응 방향은 제시하지만, 요구 확인 방법이나 거래 유지·확대 결과를 확인할 방법이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "우선 확인할 정보를 제시하지 못하거나 근거 없이 발주 감소 원인을 단정한다.",
            "발주 패턴과 거래처 요구를 확인하지 않은 채 일방적인 할인이나 구매 독촉만 제시한다.",
            "거래처와의 지속적인 접촉이나 확인된 원인에 맞는 대응이 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P12",
  "interviews": [
    {
      "categoryId": "P12-C1",
      "itemId": "P12-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "고객의 막연한 견적 요청을 사양 협의에 필요한 구체적 조건으로 전환할 수 있는지 검증한다. 질문의 초점은 필요한 장비 사양을 파악하기 위해 가장 먼저 고객에게 물을 질문이다.",
